import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlText,
  MjmlWrapper,
  MjmlColumn,
  MjmlImage,
  MjmlSection,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const CTAEmailShell = ({
  children,
  pageBackgroundColor,
  preview,
  theme,
}: {
  children: ReactNode;
  pageBackgroundColor: string;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

const CTACopy = ({
  align = "center",
  ctaHref,
  ctaLabel,
  heading,
  headingColor,
  primaryButtonBackgroundColor,
  primaryButtonTextColor,
  secondaryButtonBorderColor = "#d1d5db",
  secondaryButtonTextColor = "#4b5563",
  secondaryCtaHref,
  secondaryCtaLabel,
  subtext,
  textColor,
}: {
  align?: "center" | "left" | "right";
  ctaHref: string;
  ctaLabel: string;
  heading: string;
  headingColor: string;
  primaryButtonBackgroundColor: string;
  primaryButtonTextColor: string;
  secondaryButtonBorderColor?: string;
  secondaryButtonTextColor?: string;
  secondaryCtaHref?: string;
  secondaryCtaLabel?: string;
  subtext: string;
  textColor: string;
}) => (
  <>
    <MjmlText
      align={align}
      color={headingColor}
      fontFamily={fontFamily}
      fontSize="30px"
      fontWeight="600"
      lineHeight="36px"
      padding="0"
    >
      {heading}
    </MjmlText>
    <MjmlText
      align={align}
      color={textColor}
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="300"
      lineHeight="24px"
      padding="20px 0 0"
    >
      {subtext}
    </MjmlText>
    <MjmlButton
      align={align}
      backgroundColor={primaryButtonBackgroundColor}
      borderRadius="8px"
      color={primaryButtonTextColor}
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="500"
      href={ctaHref}
      innerPadding="10px 22px"
      lineHeight="24px"
      padding="28px 0 0"
    >
      {ctaLabel}
    </MjmlButton>
    {secondaryCtaLabel ? (
      <MjmlButton
        align={align}
        backgroundColor="transparent"
        border={`1px solid ${secondaryButtonBorderColor}`}
        borderRadius="8px"
        color={secondaryButtonTextColor}
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="500"
        href={secondaryCtaHref}
        innerPadding="9px 21px"
        lineHeight="24px"
        padding="12px 0 0"
      >
        {secondaryCtaLabel}
      </MjmlButton>
    ) : null}
  </>
);

type Cta_CTAWithTeamAvatarsVariant =
  | "default"
  | "avatars-top"
  | "single-avatar";

interface Cta_CTAWithTeamAvatarsProps {
  theme?: EmailTheme;
  heading?: string;
  subtext?: string;
  ctaLabel?: string;
  ctaHref?: string;
  secondaryCtaLabel?: string;
  secondaryCtaHref?: string;
  avatarSrc1?: string;
  avatarAlt1?: string;
  avatarSrc2?: string;
  avatarAlt2?: string;
  avatarSrc3?: string;
  avatarAlt3?: string;
  avatarSrc4?: string;
  avatarAlt4?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  primaryButtonBackgroundColor?: string;
  primaryButtonTextColor?: string;
  secondaryButtonBackgroundColor?: string;
  secondaryButtonTextColor?: string;
  secondaryButtonBorderColor?: string;
  avatarBorderColor?: string;
  variant?: Cta_CTAWithTeamAvatarsVariant;
}

const Cta_avatarSources = [
  emailAsset("reviews/avatar-2.jpg"),
  emailAsset("reviews/avatar.jpg"),
  emailAsset("reviews/avatar-4.jpg"),
  emailAsset("reviews/avatar-5.jpg"),
] as const;

const Cta_variantContent = {
  "avatars-top": {
    ctaLabel: "Confirm your email",
    heading: "The team welcomes you!",
    secondaryCtaLabel: "",
    subtext:
      "Your workspace is ready — confirm your email to join your team, collaborate seamlessly, and get started today.",
  },
  default: {
    ctaLabel: "Confirm your email",
    heading: "The team welcomes you!",
    secondaryCtaLabel: "",
    subtext:
      "Your workspace is ready — confirm your email to join your team, collaborate seamlessly, and get started today.",
  },
  "single-avatar": {
    ctaLabel: "Register now",
    heading: "Join the event",
    secondaryCtaLabel: "Learn more",
    subtext:
      "Join Jenna Hendricks, our founder and visionary, for an open discussion about what’s next for our community and how you can be part of it.",
  },
} as const;

const Cta_CTAWithTeamAvatarsSection = (
  props: Omit<Cta_CTAWithTeamAvatarsProps, "theme">
) => {
  const {
    avatarAlt1,
    avatarAlt2,
    avatarAlt3,
    avatarAlt4,
    avatarSrc1,
    avatarSrc2,
    avatarSrc3,
    avatarSrc4,
    backgroundColor,
    ctaHref,
    ctaLabel,
    heading,
    headingColor,
    primaryButtonBackgroundColor,
    primaryButtonTextColor,
    secondaryButtonBorderColor,
    secondaryButtonTextColor,
    secondaryCtaHref,
    secondaryCtaLabel,
    subtext,
    textColor,
    variant,
  } = {
    avatarAlt1: "",
    avatarAlt2: "",
    avatarAlt3: "",
    avatarAlt4: "",
    avatarSrc1: Cta_avatarSources[0],
    avatarSrc2: Cta_avatarSources[1],
    avatarSrc3: Cta_avatarSources[2],
    avatarSrc4: Cta_avatarSources[3],
    backgroundColor: "#fffffe",
    ctaHref: "https://example.com/",
    headingColor: "#030712",
    primaryButtonBackgroundColor: "#4f46e5",
    primaryButtonTextColor: "#f8fafc",
    secondaryButtonBorderColor: "#d1d5db",
    secondaryButtonTextColor: "#4b5563",
    secondaryCtaHref: "https://example.com/",
    textColor: "#4b5563",
    variant: "default" as Cta_CTAWithTeamAvatarsVariant,
    ...props,
  };
  const preset = Cta_variantContent[variant];
  const avatars = [
    { alt: avatarAlt1, src: avatarSrc1 },
    { alt: avatarAlt2, src: avatarSrc2 },
    { alt: avatarAlt3, src: avatarSrc3 },
    { alt: avatarAlt4, src: avatarSrc4 },
  ];
  const avatarRow = (
    <MjmlSection backgroundColor={backgroundColor} padding="44px 144px 12px">
      {avatars.map((avatar, index) => (
        <MjmlColumn key={`${avatar.src}-${index}`} padding="0 4px" width="25%">
          <MjmlImage
            alt={avatar.alt}
            border="2px solid #fffffe"
            borderRadius="9999px"
            padding="0"
            src={avatar.src}
            width="56px"
          />
        </MjmlColumn>
      ))}
    </MjmlSection>
  );
  let copyPadding = "44px 24px";
  if (variant === "avatars-top") {
    copyPadding = "12px 64px 44px";
  } else if (variant === "default") {
    copyPadding = "44px 64px 12px";
  }
  const copy = (
    <MjmlSection backgroundColor={backgroundColor} padding={copyPadding}>
      {variant === "single-avatar" ? (
        <MjmlColumn padding="0 24px 0 0" verticalAlign="middle" width="28%">
          <MjmlImage
            alt={avatarAlt1}
            borderRadius="9999px"
            padding="0"
            src={avatarSrc1}
            width="120px"
          />
        </MjmlColumn>
      ) : null}
      <MjmlColumn
        padding="0"
        verticalAlign="middle"
        width={variant === "single-avatar" ? "72%" : "100%"}
      >
        <CTACopy
          align={variant === "single-avatar" ? "left" : "center"}
          ctaHref={ctaHref}
          ctaLabel={ctaLabel ?? preset.ctaLabel}
          heading={heading ?? preset.heading}
          headingColor={headingColor}
          primaryButtonBackgroundColor={primaryButtonBackgroundColor}
          primaryButtonTextColor={primaryButtonTextColor}
          secondaryButtonBorderColor={secondaryButtonBorderColor}
          secondaryButtonTextColor={secondaryButtonTextColor}
          secondaryCtaHref={secondaryCtaHref}
          secondaryCtaLabel={secondaryCtaLabel ?? preset.secondaryCtaLabel}
          subtext={subtext ?? preset.subtext}
          textColor={textColor}
        />
      </MjmlColumn>
    </MjmlSection>
  );
  if (variant === "single-avatar") {
    return copy;
  }
  return (
    <>
      {variant === "avatars-top" ? avatarRow : copy}
      {variant === "avatars-top" ? copy : avatarRow}
    </>
  );
};

const Cta_CTAWithTeamAvatars = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: Cta_CTAWithTeamAvatarsProps) => (
  <CTAEmailShell
    pageBackgroundColor={pageBackgroundColor}
    preview="The team welcomes you"
    theme={theme}
  >
    <Cta_CTAWithTeamAvatarsSection {...props} />
  </CTAEmailShell>
);

Cta_CTAWithTeamAvatars.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies Cta_CTAWithTeamAvatarsProps;

const __Cta = Cta_CTAWithTeamAvatars;

export interface AvatarCallToActionProps {
  theme?: Parameters<typeof __Cta>[0]["theme"];
  heading?: string;
  description?: string;
  actions?: {
    href: string;
    label: string;
  }[];
  avatars?: {
    src: string;
    alt?: string;
  }[];
  placement?: "top" | "inline";
}

const avatarCallToActionImage = (
  avatar:
    | {
        src: string;
        alt?: string;
      }
    | undefined
) => ({
  alt: avatar?.alt,
  src: avatar?.src,
});

const avatarCallToActionLink = (
  action:
    | {
        href: string;
        label: string;
      }
    | undefined
) => ({
  href: action?.href,
  label: action?.label,
});

export const AvatarCallToAction = ({
  theme,
  heading,
  description,
  actions,
  avatars,
  placement = "inline",
}: AvatarCallToActionProps) => {
  const [first, second, third, fourth] = avatars ?? [];
  const [primaryAction, secondaryAction] = actions ?? [];
  const avatar1 = avatarCallToActionImage(first);
  const avatar2 = avatarCallToActionImage(second);
  const avatar3 = avatarCallToActionImage(third);
  const avatar4 = avatarCallToActionImage(fourth);
  const primary = avatarCallToActionLink(primaryAction);
  const secondary = avatarCallToActionLink(secondaryAction);
  let variant: Parameters<typeof __Cta>[0]["variant"] = "default";
  if (avatars?.length === 1) {
    variant = "single-avatar";
  } else if (placement === "top") {
    variant = "avatars-top";
  }
  return (
    <__Cta
      avatarAlt1={avatar1.alt}
      avatarAlt2={avatar2.alt}
      avatarAlt3={avatar3.alt}
      avatarAlt4={avatar4.alt}
      avatarSrc1={avatar1.src}
      avatarSrc2={avatar2.src}
      avatarSrc3={avatar3.src}
      avatarSrc4={avatar4.src}
      ctaHref={primary.href}
      ctaLabel={primary.label}
      heading={heading}
      secondaryCtaHref={secondary.href}
      secondaryCtaLabel={secondary.label}
      subtext={description}
      theme={theme}
      variant={variant}
    />
  );
};

AvatarCallToAction.PreviewProps = {
  placement: "inline",
} satisfies AvatarCallToActionProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
